const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav'),trigger=document.querySelector('#procedures-trigger'),mega=document.querySelector('#procedures-menu'),shade=document.querySelector('#nav-shade');
function closeMenus(){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');mega.hidden=true;shade.hidden=true;trigger.setAttribute('aria-expanded','false');document.body.style.overflow=''}
menu.addEventListener('click',()=>{const open=mobile.hidden;closeMenus();mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');if(open)document.body.style.overflow='hidden'});
function openMega(){if(innerWidth<=899)return;mega.hidden=false;shade.hidden=false;trigger.setAttribute('aria-expanded','true')}
trigger.addEventListener('click',openMega);trigger.addEventListener('mouseenter',openMega);mega.addEventListener('mouseleave',closeMenus);shade.addEventListener('click',closeMenus);shade.addEventListener('mouseenter',closeMenus);document.querySelectorAll('.apple-nav a').forEach(a=>a.addEventListener('mouseenter',closeMenus));mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenus));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(!mobile.hidden||!mega.hidden)){const open=!mega.hidden;closeMenus();(open?trigger:menu).focus()}if(e.key==='Tab'&&!mobile.hidden){const items=[menu,...[...mobile.querySelectorAll('a,summary')].filter(el=>el.getClientRects().length)];const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.addEventListener('focusin',e=>{if(!e.target.closest('.apple-nav,.mega,#mobile-nav'))closeMenus()});window.addEventListener('resize',closeMenus);
const techs={ondas:{title:'Terapia por ondas de choque.',description:'Uma das tecnologias utilizadas pelo Dr. Franz na abordagem de queixas musculoesqueléticas. A avaliação define se esse recurso faz sentido para o seu tratamento.',link:'ondas-de-choque',alt:'Dr. Franz Maier com o equipamento de ondas de choque'},magneto:{title:'Magnetoterapia.',description:'Campos magnéticos ou eletromagnéticos integram esse recurso apresentado pela clínica. Sua utilização é discutida a partir da avaliação e do plano de cuidado individual.',link:'magnetoterapia',alt:'Dr. Franz Maier ao lado de equipamentos na clínica'},ultrassom:{title:'Infiltrações guiadas por ultrassom.',description:'A imagem auxilia a visualização das estruturas e o posicionamento da agulha. A indicação e a substância utilizada são definidas conforme cada caso.',link:'infiltracoes',alt:'Dr. Franz Maier demonstra um procedimento com modelo anatômico'}};
const tabs=[...document.querySelectorAll('[data-tech]')];function selectTab(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});const key=tab.dataset.tech,t=techs[key];document.querySelector('#tech-title').textContent=t.title;document.querySelector('#tech-description').textContent=t.description;document.querySelector('#tech-photo').src='/assets/'+key+'.jpg';document.querySelector('#tech-photo').alt=t.alt;document.querySelector('#tech-counter').textContent='0'+(tabs.indexOf(tab)+1)+' / 03';document.querySelector('#tech-source').href='/procedimentos/'+t.link+'.html';document.querySelector('#tech-panel').setAttribute('aria-labelledby',tab.id)}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();selectTab(tabs[n]);tabs[n].focus()})});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.section-head,.principles article,.doctor-copy,.regenerative h2').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}


